<?php
namespace App\Http\Controllers;use App\Domain\Workflow\WebhookSignature;use App\Models\WebhookEndpoint;use App\Services\TriggerWorkflow;use DomainException;use Illuminate\Http\{JsonResponse,Request};
final class TriggerController{public function webhook(Request $r,WebhookEndpoint $endpoint,WebhookSignature $sig,TriggerWorkflow $trigger):JsonResponse{abort_unless($endpoint->enabled,404);$payload=$r->getContent();$timestamp=(int)$r->header('X-QueueFlow-Timestamp');$signature=(string)$r->header('X-QueueFlow-Signature');if(!$sig->verify($payload,$endpoint->secret_encrypted,$timestamp,$signature))return response()->json(['error'=>['code'=>'invalid_signature']],401);$delivery=(string)($r->header('X-QueueFlow-Delivery')?:hash('sha256',$timestamp.'.'.$payload));try{$execution=$trigger->trigger($endpoint->workflow,'webhook',$delivery,['payload'=>$r->json()->all()]);}catch(DomainException $e){return response()->json(['error'=>['code'=>$e->getMessage()]],429);}$endpoint->update(['last_received_at'=>now()]);return response()->json(['execution_id'=>$execution->id,'status'=>$execution->status],202);}}
